import * as crypto from 'node:crypto';
import * as fs from 'node:fs';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';

/**
 * AIRA AI 2026 — Authenticated Backup Encryption Specification
 *
 * Implements FIPS/NIST compliant Authenticated Encryption with Associated Data (AEAD):
 * - Algorithm: AES-256-GCM (Galois/Counter Mode)
 * - Key Derivation: PBKDF2 with HMAC-SHA256, 100,000 iterations, 16-byte salt
 * - Initialization Vector (IV): Cryptographically random 12 bytes per archive
 * - Authentication Tag: 16 bytes generated by GCM mode
 * - Magic Header: 8 bytes 'AIRA_ENC'
 *
 * Binary Layout:
 * [0..7]   : Magic bytes (8 bytes: "AIRA_ENC")
 * [8..23]  : Salt (16 bytes)
 * [24..35] : IV / Nonce (12 bytes)
 * [36..51] : GCM Auth Tag (16 bytes)
 * [52..N]  : AES-256-GCM Ciphertext
 */

export const MAGIC_HEADER = Buffer.from('AIRA_ENC');
export const SALT_LENGTH = 16;
export const IV_LENGTH = 12;
export const TAG_LENGTH = 16;
export const HEADER_LENGTH = MAGIC_HEADER.length + SALT_LENGTH + IV_LENGTH + TAG_LENGTH; // 8 + 16 + 12 + 16 = 52 bytes
export const PBKDF2_ITERATIONS = 100_000;
export const KEY_LENGTH = 32; // 256 bits

export interface EncryptOptions {
  passphrase: string;
  sourceFilePath: string;
  destinationEncryptedPath: string;
  removeSourceAfterEncryption?: boolean;
}

export interface DecryptOptions {
  passphrase: string;
  sourceEncryptedPath: string;
  destinationPlaintextPath: string;
}

export interface VerificationResult {
  valid: boolean;
  algorithm: string;
  saltHex: string;
  ivHex: string;
  tagHex: string;
  ciphertextBytes: number;
  error?: string;
}

/**
 * Validates that a PostgreSQL connection string for backup operations uses a direct
 * unpooled compute endpoint, rather than a connection pooler (e.g. pgBouncer / Neon pooled).
 * pg_dump requires session-level transactional isolation and cursors that poolers break.
 */
export function validateBackupConnectionUrl(connectionString: string): {
  valid: boolean;
  isDirect: boolean;
  endpoint: string;
  sanitized: string;
} {
  if (!connectionString) {
    throw new Error('Connection string must not be empty.');
  }

  // Parse host from postgres URL or format
  let host = '';
  try {
    const parsed = new URL(connectionString);
    host = parsed.hostname;
  } catch {
    const match = connectionString.match(/@([^/:?]+)/);
    host = match ? match[1] : '';
  }

  const isPooler = host.includes('-pooler');
  if (isPooler) {
    throw new Error(
      `UNPOOLED_CONNECTION_REQUIRED: Host "${host}" is a connection pooler. ` +
      'pg_dump requires a direct unpooled compute endpoint to prevent session state and cursor disruption.'
    );
  }

  const sanitized = connectionString.replace(/:\/\/[^:]+:[^@]+@/, '://[REDACTED]:[REDACTED]@');

  return {
    valid: true,
    isDirect: true,
    endpoint: host,
    sanitized
  };
}

/**
 * Derives a 256-bit AES key from a passphrase and salt using PBKDF2-HMAC-SHA256.
 */
export function deriveKey(passphrase: string, salt: Buffer): Buffer {
  if (!passphrase || passphrase.length < 8) {
    throw new Error('Encryption passphrase must be at least 8 characters long.');
  }
  return crypto.pbkdf2Sync(passphrase, salt, PBKDF2_ITERATIONS, KEY_LENGTH, 'sha256');
}

/**
 * Encrypts a source file (e.g. pg_dump archive) into an authenticated AIRA container.
 */
export async function encryptFile(options: EncryptOptions): Promise<{ destinationPath: string; bytesWritten: number; sha256: string }> {
  const { passphrase, sourceFilePath, destinationEncryptedPath, removeSourceAfterEncryption = false } = options;

  if (!fs.existsSync(sourceFilePath)) {
    throw new Error(`Source file does not exist: ${sourceFilePath}`);
  }

  const salt = crypto.randomBytes(SALT_LENGTH);
  const iv = crypto.randomBytes(IV_LENGTH);
  const key = deriveKey(passphrase, salt);

  const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
  const sourceStream = fs.createReadStream(sourceFilePath);
  const chunks: Buffer[] = [];

  for await (const chunk of sourceStream) {
    chunks.push(cipher.update(chunk));
  }
  chunks.push(cipher.final());

  const ciphertext = Buffer.concat(chunks);
  const tag = cipher.getAuthTag();

  // Construct complete container
  const container = Buffer.concat([MAGIC_HEADER, salt, iv, tag, ciphertext]);

  fs.mkdirSync(path.dirname(destinationEncryptedPath), { recursive: true });
  fs.writeFileSync(destinationEncryptedPath, container, { mode: 0o600 });

  const sha256 = crypto.createHash('sha256').update(container).digest('hex');

  if (removeSourceAfterEncryption) {
    try {
      // Securely overwrite before unlinking where feasible
      const stat = fs.statSync(sourceFilePath);
      fs.writeFileSync(sourceFilePath, crypto.randomBytes(Math.min(stat.size, 4096)));
      fs.unlinkSync(sourceFilePath);
    } catch {
      // Non-fatal if overwrite fails; ensure unlink
      if (fs.existsSync(sourceFilePath)) fs.unlinkSync(sourceFilePath);
    }
  }

  return {
    destinationPath: destinationEncryptedPath,
    bytesWritten: container.length,
    sha256
  };
}

/**
 * Decrypts an authenticated AIRA backup container with cryptographic tag verification.
 * Fails closed if the archive has been modified or the passphrase is wrong.
 */
export async function decryptFile(options: DecryptOptions): Promise<{ destinationPath: string; bytesWritten: number; sha256: string }> {
  const { passphrase, sourceEncryptedPath, destinationPlaintextPath } = options;

  if (!fs.existsSync(sourceEncryptedPath)) {
    throw new Error(`Encrypted archive does not exist: ${sourceEncryptedPath}`);
  }

  const container = fs.readFileSync(sourceEncryptedPath);
  if (container.length < HEADER_LENGTH) {
    throw new Error('Invalid backup container: file is smaller than minimum header size.');
  }

  const magic = container.subarray(0, 8);
  if (!magic.equals(MAGIC_HEADER)) {
    throw new Error('Invalid backup container: missing AIRA_ENC header signature.');
  }

  const salt = container.subarray(8, 24);
  const iv = container.subarray(24, 36);
  const tag = container.subarray(36, 52);
  const ciphertext = container.subarray(52);

  const key = deriveKey(passphrase, salt);
  const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
  decipher.setAuthTag(tag);

  let plaintext: Buffer;
  try {
    plaintext = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
  } catch (err: any) {
    throw new Error(`AUTHENTICATION_FAILED: Backup integrity verification failed. Ciphertext is corrupt or passphrase is invalid (${err.message})`);
  }

  fs.mkdirSync(path.dirname(destinationPlaintextPath), { recursive: true });
  fs.writeFileSync(destinationPlaintextPath, plaintext, { mode: 0o600 });

  const sha256 = crypto.createHash('sha256').update(plaintext).digest('hex');

  return {
    destinationPath: destinationPlaintextPath,
    bytesWritten: plaintext.length,
    sha256
  };
}

/**
 * Inspects and verifies the cryptographic integrity and metadata of an encrypted archive
 * without restoring it to disk.
 */
export function verifyArchiveContainer(archivePath: string, passphrase?: string): VerificationResult {
  if (!fs.existsSync(archivePath)) {
    return {
      valid: false,
      algorithm: 'aes-256-gcm',
      saltHex: '',
      ivHex: '',
      tagHex: '',
      ciphertextBytes: 0,
      error: `File not found: ${archivePath}`
    };
  }

  const container = fs.readFileSync(archivePath);
  if (container.length < HEADER_LENGTH) {
    return {
      valid: false,
      algorithm: 'aes-256-gcm',
      saltHex: '',
      ivHex: '',
      tagHex: '',
      ciphertextBytes: 0,
      error: 'File smaller than container header'
    };
  }

  const magic = container.subarray(0, 8);
  if (!magic.equals(MAGIC_HEADER)) {
    return {
      valid: false,
      algorithm: 'aes-256-gcm',
      saltHex: '',
      ivHex: '',
      tagHex: '',
      ciphertextBytes: 0,
      error: 'Invalid container magic bytes'
    };
  }

  const salt = container.subarray(8, 24);
  const iv = container.subarray(24, 36);
  const tag = container.subarray(36, 52);
  const ciphertext = container.subarray(52);

  let error: string | undefined;
  if (passphrase) {
    try {
      const key = deriveKey(passphrase, salt);
      const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
      decipher.setAuthTag(tag);
      decipher.update(ciphertext);
      decipher.final();
    } catch (e: any) {
      error = `AEAD authentication failed: ${e.message}`;
    }
  }

  return {
    valid: !error,
    algorithm: 'aes-256-gcm',
    saltHex: salt.toString('hex'),
    ivHex: iv.toString('hex'),
    tagHex: tag.toString('hex'),
    ciphertextBytes: ciphertext.length,
    error
  };
}

// ---------------------------------------------------------------------------
// CLI Execution Entry Point
// ---------------------------------------------------------------------------
async function runCli() {
  const args = process.argv.slice(2);
  const command = args[0];

  function getArg(flag: string): string | undefined {
    const idx = args.indexOf(flag);
    if (idx !== -1 && idx + 1 < args.length) return args[idx + 1];
    return undefined;
  }

  const hasFlag = (flag: string) => args.includes(flag);

  if (!command || hasFlag('--help') || hasFlag('-h') || command === 'help') {
    console.log(`
AIRA AI 2026 — Authenticated Backup Encryption CLI (AES-256-GCM)

Usage:
  npx tsx scripts/secure-backup-crypto.ts <command> [options]

Commands:
  encrypt    Encrypt a pg_dump archive into an authenticated AIRA_ENC container
  decrypt    Verify and decrypt an AIRA_ENC container to plaintext archive
  verify     Inspect container header and verify AEAD tag without decrypting to disk

Options:
  --source <path>        Path to source file (required)
  --dest <path>          Path to destination file (required for encrypt/decrypt)
  --passphrase <str>     Encryption passphrase (defaults to BACKUP_PASSPHRASE env var)
  --remove-source        Securely remove source file after successful encryption
  --help, -h             Show this help message

Environment Variables:
  BACKUP_PASSPHRASE      Fallback passphrase if --passphrase is not provided in args
`);
    process.exit(0);
  }

  const source = getArg('--source');
  const dest = getArg('--dest');
  const passphrase = getArg('--passphrase') || process.env.BACKUP_PASSPHRASE || process.env.AIRA_BACKUP_PASSPHRASE;
  const removeSource = hasFlag('--remove-source');

  try {
    switch (command) {
      case 'encrypt': {
        if (!source || !dest) {
          console.error('ERROR: Both --source and --dest are required for encrypt.');
          process.exit(1);
        }
        if (!passphrase) {
          console.error('ERROR: Passphrase must be provided via --passphrase or BACKUP_PASSPHRASE env var.');
          process.exit(1);
        }
        console.log(`[BACKUP_CRYPTO] Encrypting ${source} -> ${dest} (AES-256-GCM)...`);
        const result = await encryptFile({
          passphrase,
          sourceFilePath: source,
          destinationEncryptedPath: dest,
          removeSourceAfterEncryption: removeSource
        });
        console.log(`✓ Encrypted archive created successfully:`);
        console.log(`  - Destination:  ${result.destinationPath}`);
        console.log(`  - Size:         ${result.bytesWritten} bytes`);
        console.log(`  - SHA256:       ${result.sha256}`);
        break;
      }

      case 'decrypt': {
        if (!source || !dest) {
          console.error('ERROR: Both --source and --dest are required for decrypt.');
          process.exit(1);
        }
        if (!passphrase) {
          console.error('ERROR: Passphrase must be provided via --passphrase or BACKUP_PASSPHRASE env var.');
          process.exit(1);
        }
        console.log(`[BACKUP_CRYPTO] Decrypting ${source} -> ${dest} with AEAD authentication...`);
        const result = await decryptFile({
          passphrase,
          sourceEncryptedPath: source,
          destinationPlaintextPath: dest
        });
        console.log(`✓ Decrypted archive verified and restored successfully:`);
        console.log(`  - Destination:  ${result.destinationPath}`);
        console.log(`  - Size:         ${result.bytesWritten} bytes`);
        console.log(`  - SHA256:       ${result.sha256}`);
        break;
      }

      case 'verify': {
        if (!source) {
          console.error('ERROR: --source is required for verify.');
          process.exit(1);
        }
        console.log(`[BACKUP_CRYPTO] Inspecting container metadata for ${source}...`);
        const result = verifyArchiveContainer(source, passphrase);
        if (!result.valid) {
          console.error(`✗ Archive verification FAILED: ${result.error}`);
          process.exit(1);
        }
        console.log(`✓ Archive container is VALID:`);
        console.log(`  - Cipher:       ${result.algorithm}`);
        console.log(`  - Salt (hex):   ${result.saltHex}`);
        console.log(`  - IV (hex):     ${result.ivHex}`);
        console.log(`  - Tag (hex):    ${result.tagHex}`);
        console.log(`  - Ciphertext:   ${result.ciphertextBytes} bytes`);
        if (passphrase) console.log(`  - AEAD Auth:    VERIFIED (Tag matches ciphertext)`);
        break;
      }

      default:
        console.error(`ERROR: Unknown command "${command}". Run with --help for usage.`);
        process.exit(1);
    }
  } catch (err: any) {
    console.error(`✗ [BACKUP_CRYPTO_ERROR] ${err.message}`);
    process.exit(1);
  }
}

// Auto-run if executed as main CLI entry point
const currentFile = fileURLToPath(import.meta.url);
if (process.argv[1] && path.resolve(process.argv[1]) === path.resolve(currentFile)) {
  runCli();
}
